From ef1f1eac806382aa817fafa76219d1056d22b487 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 00:00:57 +0100
Subject: [PATCH] containmentlayoutmanager: cancel widget resize with Escape

Pressing Escape while dragging a desktop widget's resize handle left the
widget at its new size and quit edit mode. The handle now catches Escape
while pressed, puts back the size it had before the drag and ends it.

BUG: 451682
---
 .../containmentlayoutmanager/resizehandle.cpp | 31 +++++++++++++++++++
 .../containmentlayoutmanager/resizehandle.h   |  1 +
 2 files changed, 32 insertions(+)

diff --git a/components/containmentlayoutmanager/resizehandle.cpp b/components/containmentlayoutmanager/resizehandle.cpp
index 83f7f8c903..80fbba2614 100644
--- a/components/containmentlayoutmanager/resizehandle.cpp
+++ b/components/containmentlayoutmanager/resizehandle.cpp
@@ -7,6 +7,8 @@
 #include "resizehandle.h"

 #include <QCursor>
+#include <QKeyEvent>
+#include <QQuickWindow>
 #include <cmath>

 ResizeHandle::ResizeHandle(QQuickItem *parent)
@@ -77,6 +79,13 @@ void ResizeHandle::setPressed(bool pressed)
     }

     m_pressed = pressed;
+    if (window()) {
+        if (pressed) {
+            window()->installEventFilter(this);
+        } else {
+            window()->removeEventFilter(this);
+        }
+    }
     Q_EMIT pressedChanged();
 }

@@ -234,6 +243,28 @@ void ResizeHandle::mouseUngrabEvent()
     setPressed(false);
 }

+bool ResizeHandle::eventFilter(QObject *watched, QEvent *event)
+{
+    if (event->type() != QEvent::KeyPress || static_cast<QKeyEvent *>(event)->key() != Qt::Key_Escape) {
+        return QQuickItem::eventFilter(watched, event);
+    }
+
+    // Cancel the resize and go back to the geometry the item had when it started
+    if (m_configOverlay && m_configOverlay->itemContainer()) {
+        ItemContainer *itemContainer = m_configOverlay->itemContainer();
+        itemContainer->setPosition(m_mouseDownGeometry.topLeft());
+        itemContainer->setSize(m_mouseDownGeometry.size());
+        if (AppletsLayout *layout = itemContainer->layout()) {
+            layout->positionItem(itemContainer);
+        }
+    }
+
+    setResizeBlocked(false, false);
+    ungrabMouse();
+    setPressed(false);
+    return true;
+}
+
 void ResizeHandle::setConfigOverlay(ConfigOverlay *handle)
 {
     if (handle == m_configOverlay) {
diff --git a/components/containmentlayoutmanager/resizehandle.h b/components/containmentlayoutmanager/resizehandle.h
index f2919fd009..705e87e482 100644
--- a/components/containmentlayoutmanager/resizehandle.h
+++ b/components/containmentlayoutmanager/resizehandle.h
@@ -44,6 +44,7 @@ protected:
     void mouseReleaseEvent(QMouseEvent *event) override;
     void mouseMoveEvent(QMouseEvent *event) override;
     void mouseUngrabEvent() override;
+    bool eventFilter(QObject *watched, QEvent *event) override;

 Q_SIGNALS:
     void resizeCornerChanged();
